insert into kafaa_smr_deltas (id, role_id, tech_id, rank, path_only, dims, changes_en, changes_ar, stays_en, stays_ar, skills, training, concept_role_ids, sources, benchmark_ids, status, listed, version, as_of, sort, updated_by, updated_at) values
('smrd:procurement-engineer:tech-htgr', 'procurement-engineer', 'tech-htgr', 2, false, '[{"dim":"multi_module","change":"adapts","text_en":"Several smaller reactor modules may share one plant and one control room. Fleet purchasing of identical components across units.","text_ar":"قد تتشارك عدة وحدات مفاعل أصغر محطة واحدة وغرفة تحكم واحدة. شراء أسطولي لمكونات متطابقة عبر الوحدات."},{"dim":"digital_ic","change":"adapts","text_en":"New digital instrumentation for gas coolant and high-temperature systems. Digital procurement and obsolescence management for new platforms.","text_ar":"أجهزة رقمية جديدة لأنظمة التبريد بالغاز والأنظمة عالية الحرارة. المشتريات الرقمية وإدارة التقادم للمنصات الجديدة."},{"dim":"factory_fab","change":"new","text_en":"Reactor modules and major components are planned to be factory-built. Buying factory-built modules: supplier qualification, factory acceptance and transport logistics.","text_ar":"يُخطَّط لتصنيع وحدات المفاعل والمكونات الرئيسية في المصنع. شراء وحدات مصنّعة في المصنع: تأهيل الموردين والقبول في المصنع ولوجستيات النقل."}]'::jsonb, 'High-temperature gas-cooled: the biggest shifts for this role are factory fabrication; multi-module operation and digital I&C adapt. Planning assumption; no deployment decision implied.', 'المفاعلات عالية الحرارة المبرّدة بالغاز: أكبر التحولات لهذا الدور في التصنيع في المصنع، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Nuclear procurement discipline, commercial-grade dedication and vigilance against counterfeit items stay the same.', 'يبقى انضباط المشتريات النووية والتأهيل التجاري واليقظة تجاه المواد المزيفة كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":1},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-factoryqa","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr-x"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-dp-dic-l1"},{"kind":"pathway","ref":"pw-adv-multimodule-l1"},{"kind":"lane","ref":"lane-hydrogen"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"saskpolytech-nuclear","label":"Saskatchewan Polytechnic · Nuclear skills training (short, non-credit cross-over courses)","url":"https://saskpolytech.ca/programs-and-courses/part-time-studies/nuclear-skills-training.aspx","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 84, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:procurement-engineer:tech-micro', 'procurement-engineer', 'tech-micro', 3, false, '[{"dim":"multi_module","change":"adapts","text_en":"Many small transportable units rather than one plant. Fleet purchasing of identical components across units.","text_ar":"وحدات صغيرة كثيرة قابلة للنقل بدلاً من محطة واحدة. شراء أسطولي لمكونات متطابقة عبر الوحدات."},{"dim":"digital_ic","change":"adapts","text_en":"Remote and autonomous operation concepts: monitoring from a distance rather than from a local control room. Digital procurement and obsolescence management for new platforms.","text_ar":"مفاهيم التشغيل عن بعد والتشغيل الذاتي: المراقبة من بعيد بدلاً من غرفة تحكم محلية. المشتريات الرقمية وإدارة التقادم للمنصات الجديدة."},{"dim":"factory_fab","change":"new","text_en":"Units are built in a factory and transported as complete units. Buying factory-built modules: supplier qualification, factory acceptance and transport logistics.","text_ar":"تُبنى الوحدات في المصنع وتُنقل وحدات كاملة. شراء وحدات مصنّعة في المصنع: تأهيل الموردين والقبول في المصنع ولوجستيات النقل."}]'::jsonb, 'Microreactors: the biggest shifts for this role are factory fabrication; multi-module operation and digital I&C adapt. Planning assumption; no deployment decision implied.', 'المفاعلات المتناهية الصغر: أكبر التحولات لهذا الدور في التصنيع في المصنع، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Nuclear procurement discipline, commercial-grade dedication and vigilance against counterfeit items stay the same.', 'يبقى انضباط المشتريات النووية والتأهيل التجاري واليقظة تجاه المواد المزيفة كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":1},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-dp-dic","level":1},{"skill_id":"sk-fs-adv-factoryqa","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr-x"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-adv-micro-l1"},{"kind":"course","ref":"c-fs-remote"},{"kind":"pathway","ref":"pw-dp-dic-l1"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"saskpolytech-nuclear","label":"Saskatchewan Polytechnic · Nuclear skills training (short, non-credit cross-over courses)","url":"https://saskpolytech.ca/programs-and-courses/part-time-studies/nuclear-skills-training.aspx","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 85, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:corporate-professional:tech-intl', 'corporate-professional', 'tech-intl', 1, false, '[{"dim":"systems","change":"adapts","text_en":"Other large reactor designs, such as the AP1000, bring their own systems and documentation. Plant literacy for a new technology, so you can explain it accurately.","text_ar":"تأتي تصاميم مفاعلات كبيرة أخرى، مثل AP1000، بأنظمتها ووثائقها الخاصة. إلمام بالمحطة لتقنية جديدة كي تستطيع شرحها بدقة."},{"dim":"delivery","change":"new","text_en":"Project delivery abroad, investment and owner''s-engineer work for partners. Investment cases, partnerships and communication about projects with partners abroad.","text_ar":"تنفيذ المشاريع في الخارج والاستثمار وأعمال مهندس المالك للشركاء. دراسات الاستثمار والشراكات والتواصل بشأن المشاريع مع الشركاء في الخارج."}]'::jsonb, 'International projects: the biggest shifts for this role are project delivery; plant systems, coolant and fuel adapts. Planning assumption; no deployment decision implied.', 'المشاريع الدولية: أكبر التحولات لهذا الدور في تنفيذ المشاريع، بينما يتكيف كل من أنظمة المحطة والمبرد والوقود. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Stakeholder trust, accurate public communication and good governance stay the same.', 'تبقى ثقة أصحاب المصلحة والتواصل العام الدقيق والحوكمة الرشيدة كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":1},{"skill_id":"sk-en-01-project","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr-x"},{"kind":"course","ref":"c-fs-plantlit-x"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"nucleareurope-match","label":"nucleareurope · MATCH programme: a tool for nuclear capacity building in France","url":"https://www.nucleareurope.eu/blog/highlight-of-the-month/match-program-a-tool-for-nuclear-capacity-building-in-france/","as_of":"2026-10-10"},{"id":"saskpolytech-nuclear","label":"Saskatchewan Polytechnic · Nuclear skills training (short, non-credit cross-over courses)","url":"https://saskpolytech.ca/programs-and-courses/part-time-studies/nuclear-skills-training.aspx","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 86, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:corporate-professional:tech-bwr', 'corporate-professional', 'tech-bwr', 2, false, '[{"dim":"multi_module","change":"adapts","text_en":"A fleet of small units means several smaller reactors to run and maintain rather than a few large ones. Workforce planning for a fleet of smaller units rather than one large plant.","text_ar":"يعني أسطول من الوحدات الصغيرة تشغيل وصيانة عدد من المفاعلات الأصغر بدلاً من عدد قليل من المفاعلات الكبيرة. تخطيط القوى العاملة لأسطول من الوحدات الأصغر بدلاً من محطة كبيرة واحدة."},{"dim":"factory_fab","change":"adapts","text_en":"More of the plant arrives as factory-built modules, so quality evidence moves upstream to the factory. Contracts and finance follow factory-built delivery.","text_ar":"يصل جزء أكبر من المحطة على شكل وحدات مصنّعة في المصنع، فتنتقل أدلة الجودة إلى المصنع. تتبع العقود والشؤون المالية نموذج التسليم المصنّع في المصنع."},{"dim":"systems","change":"adapts","text_en":"A boiling water reactor makes steam in the reactor itself, so plant systems, water chemistry and radiation zones differ from Barakah''s two-loop APR-1400 units. Plant literacy for a new technology, so you can explain it accurately.","text_ar":"يولّد مفاعل الماء المغلي البخار داخل المفاعل نفسه، فتختلف أنظمة المحطة وكيمياء الماء ومناطق الإشعاع عن وحدات APR-1400 ذات الدائرتين في براكة. إلمام بالمحطة لتقنية جديدة كي تستطيع شرحها بدقة."}]'::jsonb, 'Small boiling water reactor: for this role multi-module operation, factory fabrication and plant systems, coolant and fuel adapt; the rest stays close to today. Planning assumption; no deployment decision implied.', 'مفاعل الماء المغلي الصغير: في هذا الدور يتكيف كل من التشغيل متعدد الوحدات، والتصنيع في المصنع، وأنظمة المحطة والمبرد والوقود، ويبقى الباقي قريباً مما هو عليه اليوم. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Stakeholder trust, accurate public communication and good governance stay the same.', 'تبقى ثقة أصحاب المصلحة والتواصل العام الدقيق والحوكمة الرشيدة كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":1},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-factoryqa","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr-x"},{"kind":"course","ref":"c-fs-plantlit-x"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-adv-multimodule-l1"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"gevh-smr-centre-2025","label":"GE Vernova · GE Vernova Hitachi SMR engineering and service centre, Ontario (June 2025)","url":"https://www.gevernova.com/news/press-releases/ge-vernova-hitachi-nuclear-energy-canada-small-modular-reactor-engineering-service-centre-ontario","as_of":"2026-10-10"},{"id":"saskpolytech-nuclear","label":"Saskatchewan Polytechnic · Nuclear skills training (short, non-credit cross-over courses)","url":"https://saskpolytech.ca/programs-and-courses/part-time-studies/nuclear-skills-training.aspx","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 87, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:corporate-professional:tech-micro', 'corporate-professional', 'tech-micro', 3, false, '[{"dim":"multi_module","change":"adapts","text_en":"Many small transportable units rather than one plant. Workforce planning for a fleet of smaller units rather than one large plant.","text_ar":"وحدات صغيرة كثيرة قابلة للنقل بدلاً من محطة واحدة. تخطيط القوى العاملة لأسطول من الوحدات الأصغر بدلاً من محطة كبيرة واحدة."},{"dim":"factory_fab","change":"adapts","text_en":"Units are built in a factory and transported as complete units. Contracts and finance follow factory-built delivery.","text_ar":"تُبنى الوحدات في المصنع وتُنقل وحدات كاملة. تتبع العقود والشؤون المالية نموذج التسليم المصنّع في المصنع."},{"dim":"systems","change":"adapts","text_en":"Compact designs with their own coolant and fuel choices. Plant literacy for a new technology, so you can explain it accurately.","text_ar":"تصاميم مدمجة لها خياراتها الخاصة من المبرد والوقود. إلمام بالمحطة لتقنية جديدة كي تستطيع شرحها بدقة."}]'::jsonb, 'Microreactors: for this role multi-module operation, factory fabrication and plant systems, coolant and fuel adapt; the rest stays close to today. Planning assumption; no deployment decision implied.', 'المفاعلات المتناهية الصغر: في هذا الدور يتكيف كل من التشغيل متعدد الوحدات، والتصنيع في المصنع، وأنظمة المحطة والمبرد والوقود، ويبقى الباقي قريباً مما هو عليه اليوم. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Stakeholder trust, accurate public communication and good governance stay the same.', 'تبقى ثقة أصحاب المصلحة والتواصل العام الدقيق والحوكمة الرشيدة كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":1},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-factoryqa","level":1},{"skill_id":"sk-fs-adv-micro","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr-x"},{"kind":"course","ref":"c-fs-plantlit-x"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-adv-micro-l1"},{"kind":"course","ref":"c-fs-remote"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"saskpolytech-nuclear","label":"Saskatchewan Polytechnic · Nuclear skills training (short, non-credit cross-over courses)","url":"https://saskpolytech.ca/programs-and-courses/part-time-studies/nuclear-skills-training.aspx","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'published', true, 1, '2026-10-11', 88, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:corporate-professional:tech-htgr', 'corporate-professional', 'tech-htgr', 4, false, '[{"dim":"multi_module","change":"adapts","text_en":"Several smaller reactor modules may share one plant and one control room. Workforce planning for a fleet of smaller units rather than one large plant.","text_ar":"قد تتشارك عدة وحدات مفاعل أصغر محطة واحدة وغرفة تحكم واحدة. تخطيط القوى العاملة لأسطول من الوحدات الأصغر بدلاً من محطة كبيرة واحدة."},{"dim":"factory_fab","change":"adapts","text_en":"Reactor modules and major components are planned to be factory-built. Contracts and finance follow factory-built delivery.","text_ar":"يُخطَّط لتصنيع وحدات المفاعل والمكونات الرئيسية في المصنع. تتبع العقود والشؤون المالية نموذج التسليم المصنّع في المصنع."},{"dim":"systems","change":"adapts","text_en":"Gas coolant, a different fuel form and high-temperature heat that can also serve industrial processes. Plant literacy for a new technology, so you can explain it accurately.","text_ar":"تبريد بالغاز وشكل وقود مختلف وحرارة عالية يمكن أن تخدم العمليات الصناعية أيضاً. إلمام بالمحطة لتقنية جديدة كي تستطيع شرحها بدقة."}]'::jsonb, 'High-temperature gas-cooled: for this role multi-module operation, factory fabrication and plant systems, coolant and fuel adapt; the rest stays close to today. Planning assumption; no deployment decision implied.', 'المفاعلات عالية الحرارة المبرّدة بالغاز: في هذا الدور يتكيف كل من التشغيل متعدد الوحدات، والتصنيع في المصنع، وأنظمة المحطة والمبرد والوقود، ويبقى الباقي قريباً مما هو عليه اليوم. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'Stakeholder trust, accurate public communication and good governance stay the same.', 'تبقى ثقة أصحاب المصلحة والتواصل العام الدقيق والحوكمة الرشيدة كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":1},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-factoryqa","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr-x"},{"kind":"course","ref":"c-fs-plantlit-x"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-factoryqa"},{"kind":"lane","ref":"lane-manufacturing"},{"kind":"pathway","ref":"pw-adv-multimodule-l1"},{"kind":"lane","ref":"lane-hydrogen"}]'::jsonb, '{}'::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"},{"id":"saskpolytech-nuclear","label":"Saskatchewan Polytechnic · Nuclear skills training (short, non-credit cross-over courses)","url":"https://saskpolytech.ca/programs-and-courses/part-time-studies/nuclear-skills-training.aspx","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'draft', false, 1, '2026-10-11', 89, 'p-training-mgr', '2026-10-11T08:00:00Z'),
('smrd:nuclear-training-instructor:tech-fast', 'nuclear-training-instructor', 'tech-fast', 4, false, '[{"dim":"multi_module","change":"adapts","text_en":"Fleet concepts with several units change how operations and support are organised. Training crews to coordinate across several units.","text_ar":"تغيّر مفاهيم الأساطيل متعددة الوحدات طريقة تنظيم التشغيل والدعم. تدريب الأطقم على التنسيق بين عدة وحدات."},{"dim":"passive_safety","change":"new","text_en":"Fast-reactor concepts rely on passive heat removal through the coolant''s natural circulation. New scenarios that teach crews to monitor passive systems.","text_ar":"تعتمد مفاهيم المفاعلات السريعة على إزالة الحرارة بطريقة خاملة عبر الدوران الطبيعي للمبرد. سيناريوهات جديدة تعلّم الأطقم مراقبة الأنظمة الخاملة."},{"dim":"digital_ic","change":"adapts","text_en":"Instrumentation designed for liquid-metal coolant and a fast neutron spectrum. A new simulator and digital interface to master before you teach it.","text_ar":"أجهزة مصممة لمبرد معدني سائل وطيف نيوتروني سريع. محاكٍ وواجهة رقمية جديدان يجب إتقانهما قبل تدريسهما."},{"dim":"systems","change":"new","text_en":"Liquid-metal coolant handling and chemistry, and fast-spectrum reactor physics. New plant-systems lessons, rebuilt through the systematic approach to training.","text_ar":"مناولة المبرد المعدني السائل وكيمياؤه، وفيزياء المفاعلات ذات الطيف السريع. دروس جديدة لأنظمة المحطة يُعاد بناؤها بالنهج المنهجي للتدريب."}]'::jsonb, 'Fast reactors with liquid-metal coolant: the biggest shifts for this role are passive safety and plant systems, coolant and fuel; multi-module operation and digital I&C adapt. Planning assumption; no deployment decision implied.', 'المفاعلات السريعة المبرّدة بالمعادن السائلة: أكبر التحولات لهذا الدور في السلامة الخاملة، وأنظمة المحطة والمبرد والوقود، بينما يتكيف كل من التشغيل متعدد الوحدات، والأجهزة والتحكم الرقمية. افتراض تخطيطي، ولا يعني ذلك أي قرار بالنشر.', 'The systematic approach to training, evaluation standards and instructor qualification stay the same.', 'يبقى النهج المنهجي للتدريب ومعايير التقييم وتأهيل المدربين كما هي.', '[{"skill_id":"sk-fs-adv-smr","level":2},{"skill_id":"sk-fs-adv-multimodule","level":1},{"skill_id":"sk-fs-adv-passive","level":2},{"skill_id":"sk-fs-dp-dic","level":1}]'::jsonb, '[{"kind":"microcred","ref":"MC-SMR-FOUND"},{"kind":"course","ref":"c-fs-smr"},{"kind":"pathway","ref":"pw-adv-smr-l1"},{"kind":"course","ref":"c-fs-passive"},{"kind":"pathway","ref":"pw-adv-passive-l1"},{"kind":"pathway","ref":"pw-dp-dic-l1"},{"kind":"pathway","ref":"pw-adv-multimodule-l1"},{"kind":"lane","ref":"lane-advanced"}]'::jsonb, array['fr-adv-instructor']::text[], '[{"id":"ans-smr-wf-2025","label":"ANS Nuclear Newswire · Education and training to support Canadian nuclear workforce development (26 Nov 2025)","url":"https://www.ans.org/news/2025-11-26/article-7471/education-and-training-to-support-canadian-nuclear-workforce-development/","as_of":"2026-10-10"},{"id":"iaea-ng-t-3-10","label":"IAEA NG-T-3.10 · Workforce Planning for New Nuclear Power Programmes (2011)","url":"https://www-pub.iaea.org/MTCD/Publications/PDF/Pub1477_web.pdf","as_of":"2026-10-10"}]'::jsonb, array['SMR-WF','IAEA-WFP']::text[], 'draft', false, 1, '2026-10-11', 90, 'p-training-mgr', '2026-10-11T08:00:00Z')
